test('invoiceTotals with all discount, VAT, and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 10000, discountPercent: 5, vatRate: 9 },
    ],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);

  // Line 1: qty=10, 100000, discount 10000, after 90000, bulk discount 2250, after 87750, vat 18428
  // Line 2: qty=5, 50000, discount 2500, after 47500, no bulk, vat 4275
