    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21 },
      { qty: 5, unitPrice: 10000, vatRate: 9 },
      { qty: 2, unitPrice: 10000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);

  // Line 1: qty=10, 100000, bulk 2500, after 97500, vat 20475
  // Line 2: qty=5, 50000, no bulk, vat 4500
  // Line 3: qty=2, 20000, no bulk, vat 0
  // Total discount: 2500, vat: 24975
  assert.equal(totals.subtotal, 170000);
  assert.equal(totals.discount, 2500);
  assert.equal(totals.vat, 24975);
  assert.equal(totals.total, 192475);
});

test('invoiceTotals with all discount, VAT, and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 10000, discountPercent: 5, vatRate: 9 },
    ],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);

  // Line 1: qty=10, 100000, discount 10000, after 90000, bulk discount 2250, after 87750, vat 18428
  // Line 2: qty=5, 50000, discount 2500, after 47500, no bulk, vat 4275
  // Total discount: 10000 + 2250 + 2500 = 14750
  // Total vat: 18428 + 4275 = 22703
  // Total: 150000 - 14750 + 22703 - 5000 = 152953
  assert.equal(totals.subtotal, 150000);
  assert.equal(totals.discount, 14750);
  assert.equal(totals.vat, 22703);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 152953);
});

test('invoiceTotals with bulk discount at threshold (qty=10)', () => {
