test('invoiceTotals sums line totals and includes VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 20, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', qty: 50, unitPrice: 50, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 85000, bulk 2125, after 82875, vat 17403.75 → 17404
  // Line 2: 190000, bulk 4750, after 185250, vat 38902.5 → 38902
  // Line 3: 2500, bulk 62.5 → 63, after 2437, vat 511.77 → 512
  assert.equal(totals.subtotal, 277500);
  assert.equal(totals.discount, 6938);
  assert.equal(totals.vat, 56818);
  assert.equal(totals.total, 327380);
