test('invoiceTotals subtracts voucher from total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 }).value;
  const totals = invoiceTotals(withVoucher);

  // DES-HOUR: 8500, gold tier 5% discount = 8075 after discount, VAT 21% = 1695.75 -> 1696
  // subtotal: 8500, discount: 425, vat: 1696, voucher: 5000
  // total: 8500 - 425 + 1696 - 5000 = 4771
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 5000);
});

test('invoiceTotals clamps total at 0 with large voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'BIGDISCOUNT', amount: 100000 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.total, 0);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  assert.equal(invoice.voucher, undefined);
  applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 });
  assert.equal(invoice.voucher, undefined);
});

test('applyVoucher preserves existing invoice data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 });
  assert.equal(result.value.customerId, invoice.customerId);
  assert.equal(result.value.issueDate, invoice.issueDate);
  assert.equal(result.value.status, invoice.status);
  assert.deepEqual(result.value.lines, invoice.lines);
});

