test('invoiceTotals subtracts voucher from total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 }).value;
  const totals = invoiceTotals(withVoucher);

  // DES-HOUR: 8500, gold tier 5% discount = 8075 after discount, VAT 21% = 1695.75 -> 1696
  // subtotal: 8500, discount: 425, vat: 1696, voucher: 5000
  // total: 8500 - 425 + 1696 - 5000 = 4771
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 5000);
});

