  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'BIGDISCOUNT', amount: 100000 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.total, 0);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
